import {sizeTasks,nmToM,cubeData,nanoCases} from './nano-models.js?v=20261023-physicscomplete01';
import {showNanoScale,showNanoCubes,showNanoEvidence} from './nano-scenes.js?v=20261023-physicscomplete01';
const $=s=>document.querySelector(s),btn=(id,t)=>`<button class="secondary" id="${id}">${t}</button>`;
const input=(id,title,value='')=>`<label class="field-label" for="${id}">${title}</label><input class="lab-input" id="${id}" type="number" step="any" value="${value}">`;
const select=(id,title,opts,value='')=>`<label class="field-label" for="${id}">${title}</label><select class="lab-select" id="${id}"><option value="">Choose</option>${opts.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select>`;
export function mountNanoWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.passed??=[];const pass=msg=>{p.widgetDone=true;save();done();feedback(msg);};const again=()=>{save();mountNanoWidget(l,p,root,{save,done,feedback});};
 if(l.widget==='nano-sizes'){
 w.task??=0;w.exponent??=1;w.answers??={};const i=w.task,t=sizeTasks[i];w.answers[i]??={m:'',band:''};const a=w.answers[i];root.innerHTML=`<p>Explore orders of magnitude, then convert and classify four particle sizes. Shared category boundaries are avoided in these tasks.</p><label class="field-label" for="nanoZoom">Size ruler: 10 to the power <span id="nanoPower">${w.exponent}</span> nm</label><input id="nanoZoom" type="range" min="-1" max="4" value="${w.exponent}"><p><b>Task ${i+1} / 4: diameter ${t.nm} nm</b></p>`+input('nanoMetres','Diameter in metres (e.g. 2e-8)',a.m)+select('nanoBand','Course size band',[['nano','Nanoparticle'],['fine','Fine particle'],['coarse','Coarse particle']],a.band)+btn('checkNanoSize','Check conversion and band')+btn('nextNanoSize','Next particle →')+`<p id="nanoSizeProgress">${w.passed.length} / 4 correct</p>`;showNanoScale(w.exponent);$('#nanoZoom').oninput=e=>{w.exponent=Number(e.target.value);$('#nanoPower').textContent=w.exponent;save();showNanoScale(w.exponent);};$('#nanoMetres').oninput=e=>{a.m=e.target.value;save();};$('#nanoBand').onchange=e=>{a.band=e.target.value;save();};$('#checkNanoSize').onclick=()=>{if(a.m!==''&&Number.isFinite(Number(a.m))&&Math.abs(Number(a.m)-nmToM(t.nm))<=1e-15&&a.band===t.band){if(!w.passed.includes(i))w.passed.push(i);save();$('#nanoSizeProgress').textContent=w.passed.length+' / 4 correct';feedback('Correct: '+t.nm+' nm = '+nmToM(t.nm)+' m; '+t.band+' band.');if(w.passed.length===4)pass('All four conversions and categories correct.');}else feedback('Multiply nanometres by 10⁻⁹ for metres, then use the size bands. Check the exponent sign; e-8 means ×10⁻⁸.',true);};$('#nextNanoSize').onclick=()=>{w.task=(i+1)%4;again();};return;
 }
 if(l.widget==='nano-surface'){
 if(![1,2,5].includes(w.n))w.n=1;w.answers??={};const n=w.n,d=cubeData(10,n);w.answers[n]??={area:'',volume:'',ratio:''};const a=w.answers[n];root.innerHTML='<p>Divide the same 10 nm cube into smaller cubes, separated so all their faces are exposed. Calculate for <strong>one small cube</strong>. Total material volume stays 1000 nm³.</p>'+select('nanoSplit','Subdivide along each edge',[['1','1 · one 10 nm cube'],['2','2 · eight 5 nm cubes'],['5','5 · 125 two-nm cubes']],String(n))+`<p>${d.count} particles · side ${d.side} nm each</p>`+input('nanoArea','Surface area of ONE cube / nm²',a.area)+input('nanoVolume','Volume of ONE cube / nm³',a.volume)+input('nanoRatio','SA/V for ONE cube / nm⁻¹',a.ratio)+btn('checkNanoCube','Check the calculations')+`<div id="nanoTotals" class="callout">Calculate before revealing the total exposed area.</div><p id="nanoCubeProgress">${w.passed.filter(x=>typeof x==='number').length} / 3 subdivisions calculated</p>`+select('nanoTrend','When side length decreases tenfold, SA/V…',[['up','Increases tenfold'],['down','Decreases tenfold']],w.trend||'')+btn('checkNanoTrend','Check the relationship');showNanoCubes(n);$('#nanoSplit').onchange=e=>{if(!['1','2','5'].includes(e.target.value)){e.target.value=String(w.n);return;}w.n=Number(e.target.value);again();};for(const[key,id]of[['area','nanoArea'],['volume','nanoVolume'],['ratio','nanoRatio']])$('#'+id).oninput=e=>{a[key]=e.target.value;save();};const finish=()=>{if(w.passed.length===4)pass('All three cube calculations and the inverse-size relationship are correct.');};const totals=()=>{$('#nanoTotals').textContent=`Total exposed area: ${d.totalArea} nm². Total volume: ${d.totalVolume} nm³. Ratio: ${d.ratio} nm⁻¹. Material amount is unchanged.`;};if(w.passed.includes(n))totals();$('#checkNanoCube').onclick=()=>{if(['area','volume','ratio'].every(k=>a[k]!==''&&Number.isFinite(Number(a[k]))&&Math.abs(Number(a[k])-d[k])<1e-9)){if(!w.passed.includes(n))w.passed.push(n);save();totals();$('#nanoCubeProgress').textContent=w.passed.filter(x=>typeof x==='number').length+' / 3 subdivisions calculated';feedback('Correct. SA=6d²; volume=d³; ratio=6/d.');finish();}else feedback('Use the side of one particle: SA=6d², V=d³, SA/V=6/d. The ratio has inverse-length units. Enter all three values.',true);};$('#nanoTrend').onchange=e=>{w.trend=e.target.value;save();};$('#checkNanoTrend').onclick=()=>{if(w.trend==='up'){if(!w.passed.includes('trend'))w.passed.push('trend');save();feedback('Correct: a tenfold decrease in d gives a tenfold increase in 6/d.');finish();}else feedback('SA/V is inversely proportional to side length, so smaller particles have a larger ratio.',true);};return;
 }
 w.case??=0;w.answers??={};const i=w.case,t=nanoCases[i];w.answers[i]??={benefit:'',risk:''};const a=w.answers[i];root.innerHTML=`<span class="eyebrow">FICTIONAL RESEARCH CASE ${i+1} / 3</span><h3>${t.title}</h3><p>${t.data}</p>`+select('nanoBenefit','Which benefit is supported?',[['less','Same yield using less catalyst'],['uv','Target UV protection with less whitening'],['bacteria','Reduced bacterial growth in the tested conditions']],a.benefit)+select('nanoRisk','Which missing evidence is most directly identified?',[['release','Worker exposure to airborne dust during catalyst recovery'],['inhaled','Effects at realistic inhaled aerosol exposure'],['water','Release into water and effects on aquatic organisms']],a.risk)+btn('checkNanoUse','Check the evaluation')+btn('nextNanoUse','Next case →')+`<p id="nanoUseProgress">${w.passed.length} / 3 evidence pairs justified</p><p class="micro-note">These invented results are for reasoning practice. They do not recommend real products or medical treatments.</p>`;showNanoEvidence();$('#nanoBenefit').onchange=e=>{a.benefit=e.target.value;save();};$('#nanoRisk').onchange=e=>{a.risk=e.target.value;save();};$('#checkNanoUse').onclick=()=>{if(a.benefit===t.benefit&&a.risk===t.risk){if(!w.passed.includes(i))w.passed.push(i);save();$('#nanoUseProgress').textContent=w.passed.length+' / 3 evidence pairs justified';feedback(t.why);if(w.passed.length===3)pass('All three benefits and evidence gaps identified. '+t.why);}else feedback('Use what this trial measured for the benefit, then choose the exposure question it did not answer.',true);};$('#nextNanoUse').onclick=()=>{w.case=(i+1)%3;again();};
}
